import type { LifeType } from '@/src/types/data/LifeType';

/**
 * 생활 한자어 — 카테고리별 단어 목록
 * -------------------------------------------------
 * - 한 줄이 단어 하나다. `{}` 는 예문에서 단어가 들어갈 자리 (빈칸 퀴즈·학습 카드가 함께 쓴다).
 * - 예문은 두 개씩 둔다. 같은 단어라도 쓰임이 다른 두 문장을 보여 줘야 뜻이 몸에 붙는다.
 * - 예문은 독음을 그대로 넣어 읽었을 때 조사가 자연스럽게 이어지도록 썼다.
 * - 난이도(1~4)는 한자의 획수가 아니라 그 한자어를 일상에서 얼마나 자주 쓰는지로 매겼다.
 *   1 초급(누구나 쓰는 말) → 2 중급(일상에서 흔한 말) → 3 고급(신문·업무에서 쓰는 말) → 4 특급(전문·격식어).
 * - 글자 훈음은 대표 훈음 하나만 적는다 (樂 은 '노래 악' 처럼 단어에서 읽는 음 기준).
 *
 * 2026-09-08 추가분 448개 (각 분류 181번부터)
 * - 표제어·독음   : 한자교육진흥회 교과서 한자어 · 직업분야별 실용한자어 목록 (두 글자 한자어만)
 * - 뜻풀이        : 국립국어원 표준국어대사전에서 한자 표기가 정확히 일치하는 표제어의 첫째 뜻.
 *                  30자 안에 들도록 줄여 적었고, 원문은 docs/life-word-candidates-official-2026-09-08.md 에 그대로 남겼다.
 * - 글자 훈음     : 한국어문회 배정한자 대표훈음. 다음자(覆·塞·省·狀)는 급수 자료의 부가 음훈을 따랐다.
 * - 난이도·분류·예문 : 공식 자료에 대응하는 값이 없어 이 앱에서 정하고 썼다.
 *
 * 2026-09-10 전수 점검 — 독음 전부를 표준국어대사전에 조회해 한자 표기까지 대조하고, 18개를 덜어 냈다.
 *   뺀 까닭 : 표제어가 아닌 말(赤外·兄妹·一年·數週·號線·試着) · 고유어에 한자를 빌려 적은 말(巫堂)
 *              흔한 동음이의어에 뜻이 먹히는 말(羞明=壽命 · 究竟=구경 · 二乘=이승 · 洗毛=세모 · 小房=消防 · 夫妻=부처 · 每朝)
 *              뜻이 겹치던 짝(訓音=音訓 · 約婚=婚約 · 論議=議論 · 畏敬=敬畏 — 뒤 ID 를 남겼다)
 *   빠진 ID 번호는 다시 쓰지 않는다. ID 는 순번이 아니라 열쇠다.
 *
 * 넣지 않은 말 — 사전의 첫째 뜻이 오늘 쓰는 뜻과 어긋나는 것은 뜻풀이가 있어도 뺐다.
 *   把握 '손으로 잡아 쥠' · 反映 '빛이 반사하여 비침' · 脈絡 '혈관 계통' · 萬歲 '영원히 삶'
 *   琴瑟 '거문고와 비파' · 鼓吹 '북을 치고 피리를 붊' · 右翼 '새의 오른쪽 날개' · 根幹 '뿌리와 줄기' 등.
 *   학습자가 아는 뜻과 다른 풀이를 외우게 되기 때문이다.
 *
 * 2026-09-11 뜻풀이 전수 대조 — 표준국어대사전 뜻풀이를 5046개 전부 끌어와 한 줄씩 맞대어 읽었다.
 *   고친 것 3개 : 外心 '삼각형의 바깥 중심점' → '다각형에 외접하는 원의 중심점'
 *                 次元 '길이와 넓이와 부피의 갈래' → '위치를 나타내는 데 필요한 좌표의 수'
 *                 特色 '남과 다른 특별한 빛깔' → '보통의 것과 다른 특별한 점'
 *   사전에 없던 7개는 같은 갈래의 사전 표제어로 바꿔 끼웠다 (개수는 5046 그대로).
 *     試打→打法 · 球種→打順 · 龍果→靑果 · 練肉→鷄肉 · 三鮮→乾魚 · 二層→上層 · 愛猫→愛着
 *   綠茶·紅茶는 사전이 綠차·紅차로 적지만(茶를 한자로 세지 않는다) 통용 표기라 그대로 둔다.
 *     scripts/verifyWords.mjs 의 ALLOWED 에 까닭을 적어 두었다.
 *   사전 첫째 뜻이 고어·전문어일 때 둘째 뜻(오늘 쓰는 뜻)을 쓴 것이 200개쯤 되는데, 그것은 의도한 편집이다.
 *   보기 : 經濟(사전 첫뜻 '세상을 다스리고 백성을 구제함') · 氣候('웃어른께 올리는 편지의 문안 인사')
 *          免疫·感染·腐敗(첫뜻이 모두 비유적 쓰임) · 幸福('복된 좋은 운수')
 *
 * 단어를 더하거나 고쳤으면 `yarn verify:words` 를 돌려라. 사전에 없는 말·독음이 어긋난 말을 잡아 준다.
 */
type CharTuple = [char: string, hun: string, eum: string];

const w = (
	id: string,
	word: string,
	reading: string,
	level: LifeType.Level,
	meaning: string,
	examples: [string, string],
	chars: CharTuple[],
): LifeType.Word => ({
	id,
	word,
	reading,
	level,
	meaning,
	examples,
	category: id.split('-')[0] as LifeType.CategoryKey,
	chars: chars.map(([char, hun, eum]) => ({ char, hun, eum })),
});

