/** id → 단어 */
const WORD_INDEX: Record<string, LifeType.Word> = Object.fromEntries(LIFE_WORDS.map((item) => [item.id, item]));

export const selectWord = (id: string): LifeType.Word | undefined => WORD_INDEX[id];

export const selectWordsByCategory = (category: LifeType.CategoryKey): LifeType.Word[] =>
	LIFE_WORDS.filter((item) => item.category === category);

/** 난이도별 단어 — 난이도 정복 뱃지가 "이 급수를 다 배웠나" 를 이 목록으로 센다 */
export const selectWordsByLevel = (level: LifeType.Level): LifeType.Word[] => LIFE_WORDS.filter((item) => item.level === level);

/**
 * 독음이 같고 한자가 다른 말 — 起床·氣象·氣像 처럼 213 무리, 436 개가 있다.
 * 소리만 같고 뜻이 전혀 다르므로 한자를 봐야 가려진다. 동음이의어 문항이 이 표를 쓴다.
 */
const HOMOPHONE_INDEX: Record<string, LifeType.Word[]> = LIFE_WORDS.reduce<Record<string, LifeType.Word[]>>((map, item) => {
	(map[item.reading] = map[item.reading] ?? []).push(item);
	return map;
}, {});

/** 같은 독음의 다른 단어들 (자기 자신은 뺀다). 짝이 없으면 빈 배열 */
export const selectHomophones = (word: LifeType.Word): LifeType.Word[] =>
	(HOMOPHONE_INDEX[word.reading] ?? []).filter((item) => item.id !== word.id);

/** 동음이의어 짝이 있는 단어만 — 동음이의어 문항을 낼 수 있는 후보다 */
export const HOMOPHONE_WORDS: LifeType.Word[] = LIFE_WORDS.filter((item) => (HOMOPHONE_INDEX[item.reading]?.length ?? 0) > 1);

/** 예문 하나를 고른다 — 번호가 범위를 넘어가면 다시 앞으로 돌아온다 */
export const pickExample = (word: LifeType.Word, at = 0): string => word.examples[Math.abs(at) % word.examples.length];

/** 예문의 빈칸을 채운다 — `{}` 자리에 독음(또는 원하는 글자)을 넣는다 */
export const fillExample = (word: LifeType.Word, at = 0, filler = word.reading): string => pickExample(word, at).replace('{}', filler);
